from pathlib import Path

from specforge.core.contracts import Diagnostic
from specforge.repair.context import build_repair_context, extract_symbols

SERVICE = """namespace Api.Services;

public class OrderService
{
    public decimal Sum(Guid orderId) => 0;
}
"""
GENERATED = """// <auto-generated>
//     Generated by NSwag from api/openapi.yaml
// </auto-generated>
namespace Api.Generated;

public partial class OrderDto
{
    public string Name { get; set; }
}
"""
OPENAPI = """openapi: 3.1.0
info:
  title: api
  version: 1.0.0
components:
  schemas:
    Order:
      type: object
      required: [id, name]
      properties:
        id:
          type: string
          format: uuid
        name:
          type: string
    Item:
      type: object
"""


def workspace(tmp_path: Path) -> Path:
    files = {
        "src/Api/Services/OrderService.cs": SERVICE,
        "src/Api/Generated/OrderDto.cs": GENERATED,
        "api/openapi.yaml": OPENAPI,
        "node_modules/x/OrderService.cs": "public class OrderService {}",
    }
    for rel, text in files.items():
        path = tmp_path / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text, "utf-8")
    return tmp_path


def test_extract_symbols() -> None:
    message = "'OrderService' does not contain a definition for 'Total' of type 'string'"
    assert extract_symbols(message) == ["OrderService", "Total"]
    assert extract_symbols("Cannot find name 'System.Guid'.") == []  # встроенные типы отброшены
    assert extract_symbols("a 'b' 'cc' 'dd' 'ee' 'ff'") == ["cc", "dd", "ee"]


def test_context_has_window_definitions_and_contract(tmp_path: Path) -> None:
    ws = workspace(tmp_path)
    diagnostics = [
        Diagnostic(
            tool="msbuild",
            category="compile",
            code="CS1061",
            file="src/Api/Controllers/OrdersController.cs",
            line=27,
            column=20,
            message="'OrderService' does not contain a definition for 'Total'",
            code_window=">   27 | var t = svc.Total;",
        ),
        Diagnostic(
            tool="msbuild",
            category="compile",
            code="CS8618",
            file="src/Api/Generated/OrderDto.cs",
            line=8,
            message="Non-nullable property 'Name' must contain a non-null value",
        ),
    ]
    context = build_repair_context(diagnostics, ws)
    text = context.text

    assert context.included == 2
    assert context.omitted == 0
    assert "### 1. [compile] msbuild CS1061 — src/Api/Controllers/OrdersController.cs:27:20" in text
    assert ">   27 | var t = svc.Total;" in text
    assert "- OrderService: src/Api/Services/OrderService.cs:3: public class OrderService" in text
    assert "node_modules" not in text
    assert "- Total: определение не найдено" in text
    # ошибка в сгенерированном файле → фрагмент OpenAPI для Order (имя из OrderDto)
    assert "Файл сгенерирован из контракта" in text
    assert "api/openapi.yaml:" in text
    assert "    7 |     Order:" in text
    assert "format: uuid" in text
    assert "Item:" not in text  # только блок Order
    assert context.symbols == ["OrderService", "Total", "Name"]


def test_protected_glob_counts_as_generated(tmp_path: Path) -> None:
    ws = workspace(tmp_path)
    (ws / "contracts").mkdir()
    (ws / "contracts" / "client.ts").write_text("export interface Item {}\n", "utf-8")
    d = Diagnostic(tool="tsc", file="contracts/client.ts", line=1, message="Type 'Item' is wrong")
    text = build_repair_context([d], ws, protected_globs=["contracts/**"]).text
    assert "Связанный фрагмент контракта" in text
    assert "   16 |     Item:" in text


def test_token_budget_limits_context(tmp_path: Path) -> None:
    ws = workspace(tmp_path)
    diagnostics = [
        Diagnostic(tool="tsc", code=f"TS{i}", file=f"src/f{i}.ts", line=i, message="x" * 400)
        for i in range(1, 30)
    ]
    context = build_repair_context(diagnostics, ws, budget_tokens=500)
    assert len(context.text) < 500 * 4 + 800
    assert context.included < 29
    assert context.omitted == 29 - context.included
    assert f"Не вошли в контекст ({context.omitted})" in context.text


def test_single_huge_diagnostic_is_truncated(tmp_path: Path) -> None:
    d = Diagnostic(tool="tsc", message="y" * 10_000)
    context = build_repair_context([d], tmp_path, budget_tokens=100)
    assert context.included == 1
    assert context.text.endswith("…[усечено]")
